const fs=require('fs');
const src=fs.readFileSync('services/Notifications.qml','utf8');
const shape='list.map((notif) => notifToJSON(notif)).filter(json => json !== null)';
if(!src.includes(shape)) process.exit(90);
const fields=['notificationId','actions','appIcon','appName','body','image','summary','time','urgency'];
function materialize(spec, trace, label){
  if(spec.kind!=='obj') return spec.value;
  const o={};
  for(const f of fields){
    Object.defineProperty(o,f,{enumerable:true,get(){trace.push(label+':'+f); return spec[f];}});
  }
  return o;
}
function conv(notif, trace, label){
  trace.push(label+':call');
  if(!notif){trace.push(label+':null');return null;}
  return {
    notificationId:notif.notificationId,
    actions:notif.actions,
    appIcon:notif.appIcon,
    appName:notif.appName,
    body:notif.body,
    image:notif.image,
    summary:notif.summary,
    time:notif.time,
    urgency:notif.urgency,
  };
}
function build(specs, trace){
  const a=new Array(specs.length);
  for(let i=0;i<specs.length;i++){
    const s=specs[i];
    if(s.kind==='hole') continue;
    a[i]=materialize(s,trace,'i'+i);
  }
  return a;
}
function oldSer(specs){
  const trace=[]; const a=build(specs,trace);
  const text=JSON.stringify(a.map((n,i)=>conv(n,trace,'i'+i)).filter(j=>j!==null),null,2);
  return {text,trace};
}
function newSer(specs){
  const trace=[]; const a=build(specs,trace); const out=[];
  a.forEach((n,i)=>{const j=conv(n,trace,'i'+i);if(j!==null)out.push(j);});
  const text=JSON.stringify(out,null,2);
  return {text,trace};
}
function eq(specs, code){
  const a=oldSer(specs), b=newSer(specs);
  if(a.text!==b.text) process.exit(code);
  if(JSON.stringify(a.trace)!==JSON.stringify(b.trace)) process.exit(code+1);
}
const obj=(id)=>({kind:'obj',notificationId:id,actions:[{identifier:'x'+id,text:'Open'}],appIcon:'icon'+id,appName:id%2?'App B':'App-A',body:'Body '+id,image:'',summary:'S'+id,time:id*17.5,urgency:id%3===0?'Critical':'Normal'});
eq([],10);
eq([{kind:'hole'},obj(1),{kind:'value',value:null},{kind:'hole'},obj(2)],12);
eq([{kind:'value',value:undefined},{kind:'value',value:false},{kind:'value',value:0},{kind:'value',value:''},obj(3)],14);
let seed=0x5eed1234>>>0;
function rnd(){seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed;}
for(let c=0;c<50000;c++){
  const n=rnd()%65, specs=new Array(n);
  for(let i=0;i<n;i++){
    const r=rnd()%20;
    if(r<3) specs[i]={kind:'hole'};
    else if(r===3) specs[i]={kind:'value',value:null};
    else if(r===4) specs[i]={kind:'value',value:undefined};
    else specs[i]=obj((rnd()%100000)+1);
  }
  eq(specs,20);
}
process.exit(0);
